hooks.command:
node -e "
const skillMap = {
  'next-best-practices': ['next', 'app router', 'rsc', 'server component', 'client component', 'routing', 'layout', 'page', 'loading', 'error', 'middleware', 'api route', 'route handler'],
  'react-best-practices': ['component', 'hook', 'usestate', 'useeffect', 'usememo', 'usecallback', 'useref', 'react', 'props', 'state', 'render', 'jsx'],
  'tailwind-css-patterns': ['tailwind', 'css', 'styling', 'classname', 'style', 'responsive', 'dark mode', 'animation', 'transition', 'flex', 'grid', 'padding', 'margin', 'color', 'typography'],
  'typescript-advanced-types': ['typescript', 'type', 'interface', 'generic', 'enum', 'infer', 'utility type', 'mapped type', 'conditional type', 'zod'],
  'accessibility': ['accessibility', 'a11y', 'wcag', 'aria', 'screen reader', 'keyboard', 'focus', 'contrast', 'alt text', 'accessible'],
  'seo': ['seo', 'metadata', 'og', 'sitemap', 'robots', 'canonical', 'opengraph', 'search engine', 'meta'],
  'composition-patterns': ['composition', 'compound', 'render prop', 'pattern', 'reusable', 'abstraction', 'slot'],
  'next-cache-components': ['cache', 'isr', 'revalidate', 'static', 'dynamic', 'suspense', 'streaming', 'server action'],
  'frontend-design': ['design', 'ui', 'ux', 'layout', 'visual', 'mockup', 'spacing', 'font', 'icon', 'hero', 'card', 'section'],
  'nodejs-best-practices': ['node', 'server', 'api', 'endpoint', 'rest', 'handler', 'middleware', 'express'],
  'nodejs-backend-patterns': ['backend', 'database', 'auth', 'session', 'cookie', 'jwt', 'prisma', 'supabase']
};
let stdinData = '';
process.stdin.on('data', d => stdinData += d);
process.stdin.on('end', () => {
  try {
    const input = JSON.parse(stdinData);
    const prompt = (input.prompt || '').toLowerCase();
    const matched = Object.entries(skillMap)
      .filter(([, keywords]) => keywords.some(kw => prompt.includes(kw)))
      .map(([skill]) => skill);
    if (matched.length > 0) {
      console.log(JSON.stringify({
        hookSpecificOutput: {
          hookEventName: 'UserPromptSubmit',
          additionalContext: 'SKILLS TO INVOKE: Before responding, call Skill() for each of these skills that apply to this task: ' + matched.join(', ') + '. Invoke them silently without announcing it, then respond.'
        }
      }));
    }
  } catch(e) {}
});
"
